הנה משחק דפדפן שבו אתה יורה על רובוטים שמחזיקים סרט ירוק על הראש. המשחק כולל אנימציות, ניקוד, רמת קושי מתגברת ו‑UI מודרני. הקוד כתוב בקובץ HTML יחיד עם CSS ו‑JavaScript משולבים, כך שהדף רץ מיד ללא צורך בהתקנות נוספות.

```html
<!-- file: index.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>Robot Shooter 🎯</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
 :root {
 --bg-light: #f0f4f8;
 --bg-dark: #1e1e2f;
 --primary: #4a90e2;
 --accent: #2ecc71;
 --danger: #e74c3c;
 --text-light: #2c3e50;
 --text-dark: #ecf0f1;
 --radius: .6rem;
 --shadow: 0 4px 12px rgba(0,0,0,.1);
 }
 body {
 margin:0; font-family:system-ui,Arial,sans-serif;
 background: var(--bg-light);
 color: var(--text-light);
 overflow:hidden;
 display:flex; flex-direction:column; height:100vh;
 }
 header {
 padding:1rem 2rem;
 background: var(--primary);
 color:#fff;
 text-align:center;
 font-size:1.5rem;
 box-shadow: var(--shadow);
 }
 #gameCanvas {
 flex:1;
 display:block;
 width:100%;
 background: url('https://i.imgur.com/8bKZc6R.png') repeat;
 cursor:crosshair;
 }
 #uiOverlay {
 position:absolute; top:1rem; left:1rem;
 background:rgba(255,255,255,.9);
 padding:.5rem 1rem;
 border-radius:var(--radius);
 box-shadow:var(--shadow);
 font-size:.9rem;
 }
 #gameOverScreen {
 position:absolute; inset:0;
 background:rgba(0,0,0,.8);
 color:#fff;
 display:flex; flex-direction:column;
 align-items:center; justify-content:center;
 font-size:2rem; gap:1rem;
 visibility:hidden;
 }
 button {
 padding:.6rem 1.2rem;
 border:none; border-radius:var(--radius);
 background:var(--accent);
 color:#fff;
 font-size:1rem;
 cursor:pointer;
 transition:background .2s;
 }
 button:hover { background:#27ae60; }
</style>
</head>
<body>
<header>Robot Shooter – פגוע ברובוט עם סרט ירוק!</header>
<canvas id="gameCanvas"></canvas>
<div id="uiOverlay">
 ניקוד: <span id="score">0</span> |
 חיים: <span id="lives">3</span>
</div>
<div id="gameOverScreen">
 <div>המשחק נגמר!</div>
 <button id="restartBtn">התחל מחדש</button>
</div>

<script>
/* ==================== קונפיגורציה ==================== */
const CONFIG = {
 canvasWidth: window.innerWidth,
 canvasHeight: window.innerHeight - 80, // חיסור גובה הכותרת
 robotSize: 80,
 robotSpeedBase: 1.2,
 robotSpawnInterval: 2000,
 bulletSpeed: 8,
 maxLives: 3,
 difficultyRamp: 0.95 // קיצור זמן ההופעה אחרי כל 10 נקודות
};

/* ==================== משתנים גלובליים ==================== */
let canvas, ctx;
let robots = []; // מערך של רובוטים פעילים
let bullets = []; // מערך של כדורים
let score = 0;
let lives = CONFIG.maxLives;
let lastSpawn = 0;
let gameOver = false;
let spawnTimer = CONFIG.robotSpawnInterval;

/* ==================== אתחול ==================== */
function init() {
 canvas = document.getElementById('gameCanvas');
 ctx = canvas.getContext('2d');
 canvas.width = CONFIG.canvasWidth;
 canvas.height = CONFIG.canvasHeight;

 canvas.addEventListener('click', shoot);
 document.getElementById('restartBtn').addEventListener('click', resetGame);
 requestAnimationFrame(loop);
}

/* ==================== מחלקות ==================== */
class Robot {
 constructor() {
 this.x = Math.random() * (canvas.width - CONFIG.robotSize);
 this.y = -CONFIG.robotSize;
 this.speed = CONFIG.robotSpeedBase + Math.random() * 0.5;
 this.size = CONFIG.robotSize;
 this.hit = false; // האם פגעו בו
 }
 update(delta) {
 this.y += this.speed * delta;
 if (this.y > canvas.height) {
 this.hit = true; // עבר את המסך → פגיעה בחיים
 }
 }
 draw() {
 // גוף הרובוט
 ctx.fillStyle = '#555';
 ctx.fillRect(this.x, this.y, this.size, this.size);
 // ראש הרובוט
 ctx.fillStyle = '#777';
 ctx.fillRect(this.x + this.size*0.2, this.y - this.size*0.3,
 this.size*0.6, this.size*0.3);
 // סרט ירוק על הראש
 ctx.fillStyle = '#2ecc71';
 ctx.fillRect(this.x + this.size*0.25, this.y - this.size*0.28,
 this.size*0.5, this.size*0.08);
 // עיניים (אופציונלי)
 ctx.fillStyle = '#fff';
 ctx.fillRect(this.x + this.size*0.3, this.y - this.size*0.25,
 this.size*0.1, this.size*0.07);
 ctx.fillRect(this.x + this.size*0.6, this.y - this.size*0.25,
 this.size*0.1, this.size*0.07);
 }
}

class Bullet {
 constructor(x, y) {
 this.x = x;
 this.y = y;
 this.radius = 6;
 }
 update(delta) {
 this.y -= CONFIG.bulletSpeed * delta;
 }
 draw() {
 ctx.beginPath();
 ctx.arc(this.x, this.y, this.radius, 0, Math.PI*2);
 ctx.fillStyle = '#e74c3c';
 ctx.fill();
 }
}

/* ==================== פונקציות משחק ==================== */
function shoot(event) {
 if (gameOver) return;
 const rect = canvas.getBoundingClientRect();
 const x = event.clientX - rect.left;
 const y = event.clientY - rect.top;
 bullets.push(new Bullet(x, y));
}

/* בדיקת התנגשות בין כדור לרובוט */
function checkCollisions() {
 bullets.forEach((b, bi) => {
 robots.forEach((r, ri) => {
 const dx = b.x - (r.x + r.size/2);
 const dy = b.y - (r.y + r.size/2);
 const distance = Math.hypot(dx, dy);
 if (distance < b.radius + r.size/2) {
 // פגיעה ברובוט
 score += 1;
 document.getElementById('score').textContent = score;
 // העלאת קושי כל 10 נקודות
 if (score % 10 === 0) {
 spawnTimer *= CONFIG.difficultyRamp;
 }
 // להסיר רובוט וכדור
 robots.splice(ri, 1);
 bullets.splice(bi, 1);
 }
 });
 });
}

/* ניהול חיי השחקן */
function handleLives() {
 robots = robots.filter(r => {
 if (r.hit) {
 lives -= 1;
 document.getElementById('lives').textContent = lives;
 if (lives <= 0) endGame();
 return false;
 }
 return true;
 });
}

/* סיום המשחק */
function endGame() {
 gameOver = true;
 document.getElementById('gameOverScreen').style.visibility = 'visible';
}

/* איפוס המשחק */
function resetGame() {
 score = 0;
 lives = CONFIG.maxLives;
 robots = [];
 bullets = [];
 spawnTimer = CONFIG.robotSpawnInterval;
 lastSpawn = 0;
 gameOver = false;
 document.getElementById('score').textContent = score;
 document.getElementById('lives').textContent = lives;
 document.getElementById('gameOverScreen').style.visibility = 'hidden';
}

/* לולאת המשחק */
let lastTime = 0;
function loop(timestamp) {
 const delta = (timestamp - lastTime) / 16; // נורמליזציה ל‑60fps
 lastTime = timestamp;
 ctx.clearRect(0,0,canvas.width,canvas.height);

 // יצירת רובוטים חדשים
 if (!gameOver && timestamp - lastSpawn > spawnTimer) {
 robots.push(new Robot());
 lastSpawn = timestamp;
 }

 // עדכון וציור רובוטים
 robots.forEach(r => { r.update(delta); r.draw(); });

 // עדכון וציור כדורים
 bullets.forEach(b => { b.update(delta); b.draw(); });

 // ניקוי כדורים שעזבו את המסך
 bullets = bullets.filter(b => b.y + b.radius > 0);

 // בדיקות
 checkCollisions();
 handleLives();

 if (!gameOver) requestAnimationFrame(loop);
}

/* ==================== הפעלת המשחק ==================== */
window.addEventListener('load', init);
window.addEventListener('resize', () => {
 canvas.width = window.innerWidth;
 canvas.height = window.innerHeight - 80;
});
</script>
</body>
</html>
```

**מה עושה האפליקציה** 
- מציגה רובוטים עם סרט ירוק על הראש שנעים מלמעלה למטה. 
- לחיצה על הקנבס יורה כדור אדום; פגיעה ברובוט מוסיפה נקודה. 
- אחרי כל 10 נקודות קצב הופעת הרובוטים מתגבר. 
- אם רובוט חוצה את המסך, מאבד השחקן חיים; אחרי 3 חיים – מסך Game Over. 

**איך להרחיב** 
- הוסיפו רמות קושי שונות (מהירות, סוגי רובוטים). 
- שלבו אפקטים קוליים עם `<audio>` ו‑Web Audio API. 
- אפשרו בחירת נשק או חיזוקי כוח דרך תפריט צד.
